insert into public.generated_questions
  (id, template_id, skill_id, sat_alignment, difficulty, stem, choices, correct_answer, solution, status, passage_id)
values
  ('9c090c0a-11ba-5c02-bdd1-95a5b7d663a9', null, (select id from public.skills where slug = 'read-g6-argument-evidence'), null, 'easy',
   $q$What does the author want Pinewood Elementary to do?$q$, $q$[{"text":"Start a walking school bus this year.","is_correct":true},{"text":"Build new sidewalks along Birch Road.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"Buy a new school bus for the students.","is_correct":false,"misconception_token":"literal-reading"},{"text":"Close Elm Street to all morning traffic.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Start a walking school bus this year.$q$, $q$The first paragraph says, "Pinewood Elementary should start a walking school bus this year." A walking school bus is a group of walkers, not an actual vehicle.$q$, 'draft', 'd2924bae-388e-50cc-95eb-a4a6bff6589a')
