  ('2c9ebf07-0062-5a57-87dd-30dc3e7b003a', null, (select id from public.skills where slug = 'read-g6-argument-evidence'), null, 'hard',
   $q$How does the last paragraph help a reader evaluate the two sides of the debate?$q$, $q$[{"text":"It shows the council ignored all of the evidence when it voted.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shows the bridge lasted over fifty years, so Wren's prediction proved wrong.","is_correct":true},{"text":"It shows the bridge washed away in the first flood, just as Wren warned.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shows the ferry kept running for fifty more years beside the new bridge.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It shows the bridge lasted over fifty years, so Wren's prediction proved wrong.$q$, $q$The bridge "carried wagons across the Calder for more than fifty years," which shows Wren's claim that it would "surely wash away" was wrong. The passage says nothing about the ferry continuing.$q$, 'draft', '285b6af8-886f-5a81-bd52-7ac4b44c20fb')
