-- Passage rg6-character-setting-plot-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('5fa8882b-3c4e-585d-9dec-c64cbd7631a6', 'rg6-character-setting-plot-p02', (select id from public.skills where slug = 'read-g6-character-setting-plot'), null,
        '6-8', $q$Third Chair$q$, $q$At the winter concert I sit third chair trumpet,
the seat nearest the drums and farthest from the lights.
I have practiced my solo, eight bars long,
until my lips went numb and my sister begged for quiet.

The gym is full of folding chairs and coats.
Mr. Abernathy lifts his baton.
My hands are cold. The valves feel stiff.
When my eight bars come, the first note cracks
like a plate dropped on a kitchen floor.

I want to put the trumpet down.
I want to sink below the risers and disappear.
Then I hear the drummer, Kofi, keep the beat,
steady as footsteps, as if nothing happened.

So I breathe and find the second note.
The third note is better. The fourth is mine.
I finish all eight bars, and the band rolls on
the way a river rolls around a stone.

Afterward, nobody mentions the crack.
Mr. Abernathy only nods and says, "You kept going."
At home I play the solo one more time,
loud and warm, with the window open.$q$, 'draft')
