  ('4130a715-b165-5ea4-9a68-272590d05806', null, (select id from public.skills where slug = 'read-g6-comparing-texts'), null, 'medium',
   $q$How is the kindness in Text 1 different from the kindness in Text 2?$q$, $q$[{"text":"In Text 1 the kindness fails to help, while in Text 2 the kindness clears the lane.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"In Text 1 it is done by the whole street, while in Text 2 it is done by one family in secret.","is_correct":false,"misconception_token":"reverses-texts"},{"text":"In Text 1 the helpers expect payment, while in Text 2 the helpers refuse any thanks.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"In Text 1 it is quiet and secret, while in Text 2 it is loud and shared by the whole street.","is_correct":true}]$q$::jsonb, $q$In Text 1 it is quiet and secret, while in Text 2 it is loud and shared by the whole street.$q$, $q$Hana and her father shovel "quietly" in the dark and go home "without knocking," while the poem's neighbors cheer together. Text 1's kindness works, since Mrs. Lindqvist finds a clean path.$q$, 'draft', '283a7be9-f4eb-57f6-acbd-625161abbe07')
