  ('39c811e7-b8d5-577e-a764-f6e23aa61d86', null, (select id from public.skills where slug = 'read-g6-context-clues'), null, 'medium',
   $q$Which detail from paragraph 4 best shows what "durable" means?$q$, $q$[{"text":"Some sections still stand after two thousand years.","is_correct":true},{"text":"The Romans used stone and brick.","is_correct":false,"misconception_token":"too-narrow"},{"text":"The bridges had rows of arches.","is_correct":false,"misconception_token":"wrong-context-clue"},{"text":"Most of the channel ran underground.","is_correct":false,"misconception_token":"wrong-context-clue"}]$q$::jsonb, $q$Some sections still stand after two thousand years.$q$, $q$Standing "after two thousand years" shows that durable means long-lasting. The materials are a reason the aqueducts lasted, but naming stone and brick does not by itself show what the word means.$q$, 'draft', 'a98ba625-18e8-5214-9b7f-88deae86109f')
